public class TagIndexTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            TagIndex index = new TagIndex();
            index.add("java", "Effective Java");
            index.add("java", "Java Puzzlers");
            index.add("rust", "The Book");
            index.add("java", "Effective Java");
            check("items keep insertion order", "[Effective Java, Java Puzzlers]", index.itemsFor("java").toString());
            check("duplicate item filed once", 2, index.itemsFor("java").size());
            check("second tag", "[The Book]", index.itemsFor("rust").toString());
            check("unknown tag gives empty list", "[]", index.itemsFor("go").toString());
            check("unknown tag is not null", true, index.itemsFor("go") != null);
            check("tags are sorted", "[java, rust]", index.tags().toString());
            check("distinct tag count", 2, index.size());
            index.add("go", "Go in Action");
            check("size grows with a new tag", 3, index.size());
            check("empty index size", 0, new TagIndex().size());
        } catch (Throwable t) {
            broke("TagIndex", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
